modelica_source:
model Baseline
  extends Modelica.Electrical.Analog.Examples.OpAmps.LCOscillator;
end Baseline;
model BUG024
  extends Modelica.Electrical.Analog.Examples.OpAmps.LCOscillator(opAmp(Vps=-15));
end BUG024;
model FinalBUG024
  extends Modelica.Electrical.Analog.Examples.OpAmps.LCOscillator(opAmp(final Vps=-15));
end FinalBUG024;

mos:
setCommandLineOptions("--numProcs=1 --evaluateFinalParameters=true");
setCompiler("gcc");
setCXXCompiler("g++");
loadFile("/data/mrumoca/rumoca/target/corpus/ModelicaStandardLibrary-4.1.0/Modelica/package.mo");
loadFile("/data/mrumoca/rumoca/target/corpus/ModelicaStandardLibrary-4.1.0/ModelicaTest/package.mo");
loadFile("Cases.mo");
getErrorString();
print("AUDIT_CASE Baseline\n");
simulate(Baseline, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE BUG024\n");
simulate(BUG024, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_CASE FinalBUG024\n");
simulate(FinalBUG024, stopTime=0.5, numberOfIntervals=100, outputFormat="csv");
getErrorString();
print("AUDIT_OVERRIDE BUG024\n");
system("./Baseline -override opAmp.Vps=-15 -r=BUG024_override.csv");
